import{_ as o,l as i,o as a,c as n,v as t,p as l,x as r,d,i as p,S as E}from"./chunks/framework.InCnrqk-.js";const I=JSON.parse('{"title":"流水线寄存器","description":"","frontmatter":{"title":"流水线寄存器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pipeline-registers.md","filePath":"cs/pipeline-registers.md","lastUpdated":1789023840000}'),c={name:"cs/pipeline-registers.md"};function h(_,e,m,A,M,B){const s=i("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t('<h1 id="流水线寄存器" tabindex="-1">流水线寄存器 <a class="header-anchor" href="#流水线寄存器" aria-label="Permalink to &quot;流水线寄存器&quot;">​</a></h1><div class="epigraph"><p>相邻两级之间必须有锁存：本拍算完的 PC、指令字和控制位，下一拍才能被下一级当成稳定输入。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/pipeline-five-stage">上一课</a>把通路切成 IF/ID/EX/MEM/WB，并已经点名「级间要插寄存器」。本课不重画五级，也不从组合数据通路另起。缺口是：重叠若没有隔离，后一级的组合逻辑会直接搅进前一级尚未稳定的网。本课只钉流水线寄存器里该锁什么，以及控制信号如何随指令向后走。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>五级在纸上是五段组合云。同一拍里 IF 正在取下一条，EX 正在用上一条的操作数；若 ALU 输入直接连寄存器堆读口，堆的地址已经换成新指令的 <code>rs</code>，旧指令的运算被破坏。缺口不是再加一级，而是<strong>每级边界上的锁存：只让本级在时钟沿把产出交给下级，级内组合在一拍内算完</strong>。</p><p>控制同样要走寄存器。上一课假定真值表在一拍里驱动整条通路；重叠之后，MEM 的 <code>MemWrite</code> 必须属于正在访存的那条指令，而不能属于刚在 ID 译出的那条。</p><p><span class="marginnote">教学机常画 IF/ID、ID/EX、EX/MEM、MEM/WB 四组。WB 写堆发生在时钟沿，通常不再需要第五组「WB 之后」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>IF/ID 锁 PC+4 与指令字。ID/EX 锁两个操作数、立即数、目的寄存器号，以及 EX/MEM/WB 要用的控制位。EX/MEM 锁 ALU 结果、要写的数据、分支条件。MEM/WB 锁从存储器或 ALU 来的写回值与目的号。</p>',9)),(a(),l(E,null,{default:r(()=>[p(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20IF%5B%22IF%20%E7%BB%84%E5%90%88%22%5D%20--%3E%20R1%5B%22IF%2FID%20%E9%94%81%E5%AD%98%22%5D%0A%20%20R1%20--%3E%20ID%5B%22ID%20%E7%BB%84%E5%90%88%22%5D%0A%20%20ID%20--%3E%20R2%5B%22ID%2FEX%20%E9%94%81%E5%AD%98%22%5D%0A%20%20R2%20--%3E%20EX%5B%22EX%20%E7%BB%84%E5%90%88%22%5D%0A%20%20EX%20--%3E%20R3%5B%22EX%2FMEM%20%E9%94%81%E5%AD%98%22%5D%0A%20%20R3%20--%3E%20MEM%5B%22MEM%20%E7%BB%84%E5%90%88%22%5D%0A%20%20MEM%20--%3E%20R4%5B%22MEM%2FWB%20%E9%94%81%E5%AD%98%22%5D%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>停顿与冲刷后课才引入：本课假定每拍四组都装新值。气泡在后课里就是把某组控制位置成「不写、不访存」的 NOP。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>锁存把「同时在飞的几条指令」变成几份互不干扰的快照。程序员仍看见顺序 ISA：写回值来自 MEM/WB，与 IF 正在取的那条无关。时钟周期覆盖最慢一级的组合延迟<strong>加上</strong>寄存器建立时间；上一课说的「时钟收到最慢一段」在本课才有对象。</p><p>目的寄存器号必须随指令走完 WB。否则写回时堆地址会用错成更年轻指令的 <code>rd</code>。这不是数据冒险——值可以是对的——而是控制与标识没有随流水线前进。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不检测相关，不插入气泡，不冲刷。结构上两级抢同一端口，是<a href="/cs/structural-hazard">结构冒险</a>的缺口。也不把流水线寄存器当成 ISA 可见状态：调试器看见的是提交后的架构寄存器。</p><p>后课默认：谈到经典五级，级间有四组锁存，控制位随指令前进。理想情况下每拍各组前进一格。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>重叠靠级间锁存隔离组合网；没有它们，后级会改写前级的输入。</li><li>操作数、PC、<code>rd</code> 和控制位都要随指令走完该走的级。</li><li>结构冲突与 RAW 转发都是后课的缺口。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V 流水线数据通路；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',9))])}const u=o(c,[["render",h]]);export{I as __pageData,u as default};
